create temp table want_ledger (month date, pattern text, pulls int, source text, ledger_lines int, ledger_cents bigint);
select is((select count(*) from want_ledger w join (public.v_dumpster_month d join public.waste_vendors v on v.id = d.waste_vendor_id)
  on d.job_number = '50-60-225120' and d.month = w.month and v.pattern = w.pattern and d.pulls is not distinct from w.pulls and d.source = w.source and d.ledger_lines = w.ledger_lines and d.ledger_cents = w.ledger_cents),
  4::bigint, 'from the ledger alone: a pull a line for the hauler that bills that way (a credit takes one back), spend only for the lump');
select is((select count(*) from public.v_recurring_candidates where job_number = '50-60-225120'), 0::bigint, 'the hauler''s $685 lines are not a recurring rental');
create temp table want_log (month date, pattern text, pulls int, source text, entries int, haul_lines int);
select is((select count(*) from want_log w join (public.v_dumpster_month d join public.waste_vendors v on v.id = d.waste_vendor_id)
  on d.job_number = '50-60-225120' and d.month = w.month and v.pattern = w.pattern and d.pulls is not distinct from w.pulls and d.source = w.source and d.entries = w.entries and d.haul_lines = w.haul_lines),
  4::bigint, 'with the log: it wins for the vendor and month it has entries for, the ledger count stays beside it');
select is((select log_cost_cents from public.v_dumpster_month d join public.waste_vendors v on v.id = d.waste_vendor_id where d.job_number = '50-60-225120' and d.month = '2026-08-01' and v.pattern = 'sourgum'), 479500::bigint, 'the log''s cost rides along');
select is((select pulls from public.v_dumpster_month where job_number = '50-60-225120' and month = '2026-09-01' and waste_vendor_id is null), 2, 'a hauler Settings does not know still logs');
